-- File METADATA lives here; the file's bytes live in object storage (MinIO / S3), addressed by
-- storage_key (spec section 18). The key is generated by us and never contains the user's filename.
CREATE TABLE file_attachments (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id   UUID         NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    project_id        UUID         NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    task_id           UUID         NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    uploaded_by       UUID         NOT NULL REFERENCES users(id),
    original_filename VARCHAR(255) NOT NULL,
    -- The type we DETECTED from the file's content, not the one the browser claimed.
    content_type      VARCHAR(100) NOT NULL,
    size_bytes        BIGINT       NOT NULL CHECK (size_bytes > 0),
    sha256            VARCHAR(64) NOT NULL,
    storage_key       VARCHAR(200) NOT NULL UNIQUE,
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE INDEX idx_file_attachments_task_id ON file_attachments (task_id);
CREATE INDEX idx_file_attachments_org_id ON file_attachments (organization_id);
